    public static void escalate(Set<Id> ticketIds) {
        // 1. Get the tickets the user can see (respecting sharing)
        List<FB_Ticket__c> visibleTickets = [SELECT Id FROM FB_Ticket__c WHERE Id IN :ticketIds];

        if (!visibleTickets.isEmpty()) {
            // 2. Perform the update and audit creation without sharing
            new EscalationHelper().performEscalation(visibleTickets);
        }
    }

    private without sharing class EscalationHelper {
        public void performEscalation(List<FB_Ticket__c> tickets) {
            List<FB_Ticket_Audit__c> audits = new List<FB_Ticket_Audit__c>();
            for (FB_Ticket__c t : tickets) {
                t.Priority__c = 'High';
                audits.add(new FB_Ticket_Audit__c(Ticket_Id__c = t.Id, Action__c = 'Escalated'));
            }
            update tickets;
            insert audits;
        }
    }
