public class ContactTriggerHandler {
    private static Map<Id, Account> accountMap;

    /**
     * Handles before insert and before update logic.
     * 1. Sets MailingCountry from Account.BillingCountry if blank.
     * 2. Sets LeadSource from Account.AccountSource if insert and blank.
     */
    public static void before(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Query accounts once and cache them in a static map to be reused in after context
        if (accountMap == null) {
            accountMap = new Map<Id, Account>([
                SELECT Id, BillingCountry, AccountSource, Phone 
                FROM Account 
                WHERE Id IN :accountIds
            ]);
        }

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                Account a = accountMap.get(c.AccountId);
                if (a != null) {
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    if (isInsert && String.isBlank(c.LeadSource)) {
                        c.LeadSource = a.AccountSource;
                    }
                }
            }
        }
    }

    /**
     * Handles after insert logic.
     * 1. If Account.Phone is blank and Contact.Phone is not blank, update Account.Phone.
     * 2. If multiple contacts share an account, the first in trigger order sets the phone.
     */
    public static void afterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Ensure accountMap is populated (in case before context was not entered)
        if (accountMap == null) {
            accountMap = new Map<Id, Account>([
                SELECT Id, BillingCountry, AccountSource, Phone 
                FROM Account 
                WHERE Id IN :accountIds
            ]);
        }

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Account a = accountMap.get(c.AccountId);
                // Check if account exists and if the phone is currently blank
                if (a != null && String.isBlank(a.Phone)) {
                    /* 
                       To respect the "first contact in trigger order" rule:
                       The loop follows Trigger.new order. Once the first contact 
                       updates the phone field on the 'a' object in the accountMap, 
                       subsequent contacts for the same account will see the 
                       updated value in 'a.Phone' via the map reference, 
                       meaning String.isBlank(a.Phone) will be false.
                    */
                    a.Phone = c.Phone;
                    accountsToUpdate.put(a.Id, a);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
