    public class PicklistService {
        public class Option {
            @AuraEnabled public String value;
            @AuraEnabled public String label;
            @AuraEnabled public Boolean isDefault;
            public Option(String v, String l, Boolean d) {
                this.value = v;
                this.label = l;
                this.isDefault = d;
            }
        }

        public class PicklistServiceException extends Exception {}

        public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
            if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Object and field names must be provided.');
            }

            Map<String, Schema.SObjectType> gd = Schema.getGlobalDescribe();
            Schema.SObjectType sObjectType = gd.get(objectApiName);

            // Case-insensitive lookup for Object
            if (sObjectType == null) {
                for (String key : gd.keySet()) {
                    if (key.equalsIgnoreCase(objectApiName)) {
                        sObjectType = gd.get(key);
                        break;
                    }
                }
            }

            if (sObjectType == null) {
                throw new PicklistServiceException('Object ' + objectApiName + ' does not exist.');
            }

            Schema.DescribeSObjectResult objDescribe = sObjectType.getDescribe();
            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
            Schema.SObjectField field = fieldMap.get(fieldApiName);

            // Case-insensitive lookup for Field
            if (field == null) {
                for (String key : fieldMap.keySet()) {
                    if (key.equalsIgnoreCase(fieldApiName)) {
                        field = fieldMap.get(key);
                        break;
                    }
                }
            }

            if (field == null) {
                throw new PicklistServiceException('Field ' + fieldApiName + ' does not exist on object ' + objectApiName + '.');
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();

            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException('Field ' + fieldApiName + ' is not a picklist or multi-select picklist.');
            }

            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(new Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefault()
                    ));
                }
            }

            return options;
        }
    }
