        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        // Fetch accounts to update
        List<Account> accountsToUpdate = [SELECT Id, Description FROM Account WHERE Id IN :accountIds];

        for (Account acc : accountsToUpdate) {
            acc.Description = 'Synced to ERP';
        }

        // Perform update. If any fail, the entire transaction rolls back.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
