                Decimal totalAmount = (Decimal)ar.get('totalAmount');

                // Update the map with the sum. 
                // We check containsKey just in case, although the WHERE clause 
                // ensures the AccountId is in the input set.
                if (resultMap.containsKey(accId)) {
