    public class AccountOnboardingService {
        public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
            List<Account> accountsToReturn = new List<Account>();

            if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
                return accountsToReturn;
            }

            // Initialize UOW with the types of SObjects we are working with
            fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
                new List<SObjectType> { Account.SObjectType, Contact.SObjectType }
            );

            for (String accName : contactLastNamesByAccountName.keySet()) {
                List<String> lastNames = contactLastNamesByAccountName.get(accName);

                Account newAcc = new Account(Name = accName);
                uow.registerNew(newAcc);
                accountsToReturn.add(newAcc);

                if (lastNames != null) {
                    for (String lastName : lastNames) {
                        Contact newCon = new Contact(LastName = lastName);
                        uow.registerNew(newCon);
                        // Relate contact to the account
                        uow.registerRelationship(newCon, Account.SObjectType, 'AccountId', newAcc);
                    }
                }
            }

            uow.commitWork();

            return accountsToReturn;
        }
    }
