     * @return A list of the newly created Account records with their IDs populated.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> accountsToReturn = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return accountsToReturn;
        }

        // Initialize the Unit of Work with the SObject types involved.
        // This ensures DML is performed in the correct order (Parents then Children).
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType> { Account.SObjectType, Contact.SObjectType }
        );

        for (Map.Entry<String, List<String>> entry : contactLastNamesByAccountName.entrySet()) {
            String accountName = entry.getKey();
            List<String> lastNames = entry.getValue();

            // Create the Account record
            Account newAcc = new Account(Name = accountName);

            // Register the new Account with the UOW
            uow.registerNew(newAcc);

            // Add to the return list (the UOW will populate the ID after commitWork)
            accountsToReturn.add(newAcc);

            // Process the list of contact last names for this specific account
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    // Create the Contact record
                    Contact newCon = new Contact(LastName = lastName);

                    // Register the new Contact with the UOW
                    uow.registerNew(newCon);

                    // Establish the relationship between the Contact and the Account.
                    // We use the field API name 'AccountId' to link them.
                    // The UOW handles the ID assignment once the Account is inserted.
                    uow.registerRelationship(newCon, Account.SObjectType, 'AccountId', newAcc);
                }
            }
        }

        // Commit all registered changes in a single transaction.
        // This performs the DML operations in the correct order.
        uow.commitWork();

        return accountsToReturn;
    }
