                Map<String, Id> emailToIdMap = new Map<String, Id>();
                // We need to handle case-insensitivity.
                // The contact.Email in SOQL is case-insensitive.
                // Let's use a Map where the key is the lowercase email.
                if (!emailSet.isEmpty()) {
                    // Query contacts. The order by handles the "first created" rule.
                    // Since we want the earliest, we sort by CreatedDate ASC, Id ASC.
                    // We only keep the FIRST one found for each email.
                    for (Contact c : [SELECT Id, Email FROM Contact WHERE Email IN :emailSet ORDER BY CreatedDate ASC, Id ASC]) {
                        String cEmail = c.Email.toLowerCase();
                        if (!emailToIdMap.containsKey(cEmail)) {
                            emailToIdMap.put(cEmail, c.Id);
                        }
                    }
