                for (String email : cleanedEmails) {
                    Result res = new Result();
                    if (email != null && email != '') {
                        res.contactId = emailToIdMap.get(email.toLowerCase());
                    } else {
                        res.contactId = null;
                    }
                    results.add(res);
                }
                return results;
            }
        }
