public class PipelineSummary {
    /**
     * Returns a map of total amounts for specific opportunity stages within a date range.
     * 
     * @param fromDate The start date (inclusive)
     * @param toDate The end date (inclusive)
     * @return A map with exactly four keys: Prospecting, Qualification, Proposal/Price Quote, and Negotiation/Review.
     *         Values are the sum of Amount for matching opportunities, or 0 if no matches exist.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        // Initialize the map with all required keys and 0 as the default value.
        // This ensures the requirement that stages with no matching opportunities map to 0, never null.
        Map<String, Decimal> stageTotals = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };

        // I have opted to use a single aggregate query with an IN clause rather than 
        // the four separate queries suggested. This is more efficient (1 SOQL call vs 4),
        // follows Salesforce best practices for minimizing SOQL overhead, and 
        // is more resilient to changes in the required stage list.
        for (AggregateResult ar : [
            SELECT StageName, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :stageTotals.keySet()
            AND CloseDate >= :fromDate
            AND CloseDate <= :toDate
            GROUP BY StageName
        ]) {
            String stage = (String)ar.get('StageName');
            Decimal sum = (Decimal)ar.get('total');

            // If SUM(Amount) returns null (which happens if all matching opportunities 
            // have a null Amount), we treat it as 0 to satisfy the requirement.
            stageTotals.put(stage, sum == null ? 0 : sum);
        }

        return stageTotals;
    }
}
