public with sharing class CasePriorityHandler {
    /**
     * Sets Case priority to 'High' if the associated Account has a 'Hot' rating.
     * This method is bulkified to handle batches of up to 200 records (and beyond)
     * without hitting SOQL governor limits.
     */
    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();

        // Step 1: Collect all AccountIds from the incoming cases to avoid querying in a loop
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // If no accounts are associated with the new cases, we can exit early
        if (accountIds.isEmpty()) {
            return;
        }

        // Step 2: Perform a single query to get all necessary Account data
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // Step 3: Iterate through the cases and apply priority logic
        for (Case c : newCases) {
            // Only process cases that have an associated account
            if (c.AccountId != null && accountMap.containsKey(c.AccountId)) {
                Account parentAcc = accountMap.get(c.AccountId);

                // If the account is 'Hot', update the priority to 'High'
                if (parentAcc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
            // Note: If the condition is not met, 'c.Priority' remains unchanged,
            // preserving the value provided during creation as requested.
        }
    }
}
