public class AccountRatingService {
    /**
     * Recalculates the Rating of Accounts based on their open opportunities.
     * Hot: At least one open opportunity with Amount >= 100,000.
     * Warm: Has open opportunities but none >= 100,000.
     * Cold: No open opportunities.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Map to store the maximum amount of an open opportunity per account
        Map<Id, Decimal> maxAmountMap = new Map<Id, Decimal>();
        // Set to track which accounts have at least one open opportunity
        Set<Id> accountsWithOpenOpps = new Set<Id>();

        // Use aggregate query to efficiently find the max amount for open opportunities
        for (AggregateResult ar : [
            SELECT AccountId, MAX(Amount) maxAmt 
            FROM Opportunity 
            WHERE AccountId IN :accountIds AND IsClosed = false 
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            accountsWithOpenOpps.add(accId);
            maxAmountMap.put(accId, (Decimal)ar.get('maxAmt'));
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accId : accountIds) {
            String rating;

            if (!accountsWithOpenOpps.contains(accId)) {
                // No open opportunities found
                rating = 'Cold';
            } else {
