public with sharing class LineItemDiscountHandler {
    /**
     * Handles logic for new OpportunityLineItems before they are inserted.
     * Sets default discounts based on Product Family if no discount is provided.
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newItems) {
        Set<Id> productIds = new Set<Id>();

        // First pass: Identify products that need a discount applied
        for (OpportunityLineItem oli : newItems) {
            if (oli.Discount__c == null && oli.Product2Id != null) {
                productIds.add(oli.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // Bulk query Product families to avoid SOQL in a loop
        Map<Id, Product2> productMap = new Map<Id, Product2>([
            SELECT Id, Family 
            FROM Product2 
            WHERE Id IN :productIds
        ]);

        // Second pass: Apply the standard discount using the existing PricingRules logic
        for (OpportunityLineItem oli : newItems) {
            if (oli.Discount__c == null && oli.Product2Id != null) {
                Product2 prod = productMap.get(oli.Product2Id);
                if (prod != null) {
                    // Using standardDiscountForFamily ensures rules stay in one place
                    oli.Discount__c = PricingRules.standardDiscountForFamily(prod.Family);
                }
            }
        }
    }
}
