    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> results = new List<Id>();

        // Return an empty list if the leads input is null
        if (leads == null) {
            return results;
        }

        // To avoid an O(N*M) nested loop, we use a Map for O(N+M) complexity.
        // This provides much better scalability as the volume of records grows.
        // The map stores the normalized email as the key and the first encountered Contact Id as the value.
        Map<String, Id> emailToContactIdMap = new Map<String, Id>();

        if (contacts != null) {
            for (Contact con : contacts) {
                // A contact with a blank email never matches
                if (String.isNotBlank(con.Email)) {
                    // Normalize email: remove leading/trailing spaces and ignore case
                    String normalizedEmail = con.Email.trim().toLowerCase();

                    // "when several contacts have the lead's email, return the first one in contacts order"
                    // We only add the email to the map if it hasn't been encountered before.
                    if (!emailToContactIdMap.containsKey(normalizedEmail)) {
                        emailToContactIdMap.put(normalizedEmail, con.Id);
                    }
                }
            }
        }

        // Iterate through leads to build the results list in the original order
        for (Lead ld : leads) {
            Id matchedId = null;

            // A lead with a blank email never matches
            if (String.isNotBlank(ld.Email)) {
