    public class RenewalReminderService {
        /**
         * Sends reminder emails to opportunity owners.
         *
         * NOTE: The requirement to call Messaging.sendEmail inside the loop is a bad practice.
         * 1. It is highly inefficient and increases the risk of hitting governor limits (e.g., total number of callouts/emails).
         * 2. It significantly increases the execution time of the transaction.
         * 3. The best practice is to batch emails into a single Messaging.sendEmail(List<Messaging.SingleEmailMessage>) call.
         *
         * @param opportunityIds List of Opportunity IDs to process.
         * @return Integer the number of emails successfully queued.
         */
        public static Integer sendReminders(List<Id> opportunityIds) {
            if (opportunityIds == null || opportunityIds.isEmpty()) {
                return 0;
            }

            List<Opportunity> opps = [
                SELECT Id, Name, CloseDate, OwnerId
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ];

            Integer successCount = 0;

            for (Opportunity opp : opps) {
                try {
                    Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
                    email.setTargetObjectId(opp.OwnerId);
                    email.setSaveAsActivity(false);
                    email.setSubject('Renewal due: ' + opp.Name);
                    email.setPlainTextBody('The renewal is due on ' + opp.CloseDate);

                    // Per requirement: Call sendEmail inside the loop to isolate failures.
                    Messaging.sendEmail(new List<Messaging.SingleEmailMessage>{email});
                    successCount++;
                } catch (Exception e) {
                    // If one email fails, catch the exception so the loop continues.
                    // In a production environment, consider logging this error (e.g., via a custom error log object).
                }
            }

            return successCount;
        }
    }
