    /**
     * @description Synchronizes MailingCountry on Contacts when an Account's BillingCountry changes.
     * @param newAccounts The list of accounts from Trigger.new
     * @param oldAccountMap The map of accounts from Trigger.oldMap
     */
    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        Set<Id> accountIdsToProcess = new Set<Id>();
        Map<Id, String> oldCountryMap = new Map<Id, String>();
        Map<Id, String> newCountryMap = new Map<Id, String>();

        // 1. Identify which accounts had a change in BillingCountry
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                accountIdsToProcess.add(acc.Id);
                oldCountryMap.put(acc.Id, oldAcc.BillingCountry);
                newCountryMap.put(acc.Id, acc.BillingCountry);
            }
        }

        // If no countries changed, exit early
        if (accountIdsToProcess.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // 2. Query only the contacts related to the affected accounts.
        // This fulfills the requirement of "one query" while being scale-safe.
        for (Contact con : [SELECT Id, AccountId, MailingCountry FROM Contact WHERE AccountId IN :accountIdsToProcess]) {
            String oldCountry = oldCountryMap.get(con.AccountId);
            String newCountry = newCountryMap.get(con.AccountId);

            // Condition: MailingCountry is blank OR equal to the account's previous BillingCountry
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // 3. Perform bulk update
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
