    _options = [];
    _value = '';
    activeOptionIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        this.syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.syncActiveIndex();
