     * Per requirements: The active option starts as the selected option, 
     * or the first option if nothing is selected.
     */
    syncActiveIndex() {
        if (this._options.length > 0) {
            const index = this._options.findIndex(opt => opt.value === this._value);
            this.activeOptionIndex = index !== -1 ? index : 0;
        } else {
            this.activeOptionIndex = 0;
        }
    }

