     * Returns the ID of the currently active (focused via keyboard) option.
     * Used for the aria-activedescendant attribute.
     */
    get activeId() {
        const options = this.processedOptions;
        if (options.length > 0) {
            // Ensure index is clamped to valid range
            const idx = Math.max(0, Math.min(this.activeOptionIndex, options.length - 1));
            return options[idx].id;
        }
        return '';
    }

    /**
     * Handles keyboard navigation for the listbox.
     */
    handleKeyDown(event) {
        const len = this._options.length;
        if (len === 0) return;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this.activeOptionIndex < len - 1) {
                    this.activeOptionIndex++;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this.activeOptionIndex > 0) {
                    this.activeOptionIndex--;
                }
                break;
            case 'Home':
                event.preventDefault();
                this.activeOptionIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this.activeOptionIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.handleSelection(this._options[this.activeOptionIndex].value);
                break;
            default:
                // Allow default behavior for other keys (like Tab)
                break;
        }
    }

