import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value ? value.toUpperCase() : '';
    }

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value ? value.map(task => ({ ...task })) : [];
        this.items = [...this._tasks];
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmedLabel = this.newLabel.trim();
        if (!trimmedLabel) {
            return;
        }

        const newTask = {
            id: `new-${this.nextId++}`,
            label: trimmedLabel,
            done: false
        };

        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', {
            detail: { label: trimmedLabel }
        }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        this.items = this.items.map(task => {
            if (task.id === taskId) {
                return { ...task, done: !task.done };
            }
            return task;
        });
    }
}
