     * @param members A list of new Contact records (no Id, no AccountId).
     * @return The Id of the newly created Household Account.
     * @throws IllegalArgumentException if members is null or empty, or if NPSP automation fails.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('The members list cannot be null or empty.');
        }

        // Insert the first contact. 
        // In NPSP, inserting a Contact without an AccountId triggers the creation 
        // of a Household Account via NPSP automation (Contact trigger).
        insert members[0];

        // Since NPSP's Household creation and the subsequent update to the Contact's 
        // AccountId happens in an 'after insert' trigger, we must query the contact 
        // to retrieve the newly assigned AccountId.
        Contact insertedContact = [
            SELECT AccountId 
            FROM Contact 
            WHERE Id = :members[0].Id 
            LIMIT 1
        ];

        Id householdId = insertedContact.AccountId;

        // If NPSP automation did not create an account (e.g., settings changed),
        // we cannot proceed as we cannot group the members into one household.
        if (householdId == null) {
            throw new IllegalArgumentException('NPSP automation failed to create a Household Account.');
        }

        // If there are more members in the list, associate them with the same Household Account.
        if (members.size() > 1) {
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = householdId;
            }
            // Insert the remaining contacts.
            insert members.subList(1, members.size());
        }

        return householdId;
    }
}
