public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Adds or updates partial soft credits for peer-to-peer fundraising.
     * Ensures the contact has exactly one OpportunityContactRole on the opportunity with the specified role.
     * Validates all requests before any DML is performed.
     * 
     * @param requests List of SoftCreditRequest objects.
     * @throws SoftCreditException if validation fails.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) {
                oppIds.add(req.opportunityId);
            }
            if (req.contactId != null) {
                contactIds.add(req.contactId);
            }
        }

        // SOQL 1: Retrieve Opportunity details for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c 
            FROM Opportunity 
            WHERE Id IN :oppIds
        ]);

        // 1. Validate the whole call before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }

            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be a positive non-null value.');
            }

            Decimal oppAmount = (opp.Amount == null) ? 0 : opp.Amount;
            if (req.amount > oppAmount) {
                throw new SoftCreditException('Amount exceeds the opportunity amount.');
            }

            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact cannot be the primary contact of the opportunity.');
            }
        }

        // SOQL 2: Retrieve existing OpportunityContactRoles
        // Grouped by a composite key of OppId + ContactId
        Map<String, List<OpportunityContactRole>> allOcrsByContactOpp = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, OpportunityId, Role 
            FROM OpportunityContactRole 
            WHERE ContactId IN :contactIds AND OpportunityId IN :oppIds
        ]) {
            String key = (String)ocr.OpportunityId + '-' + (String)ocr.ContactId;
            if (!allOcrsByContactOpp.containsKey(key)) {
                allOcrsByContactOpp.put(key, new List<OpportunityContactRole>());
            }
            allOcrsByContactOpp.get(key).add(ocr);
        }

        // SOQL 3: Retrieve existing NPSP Soft Credits
        Map<String, npsp__SoftCredit__c> scMap = new Map<String, npsp__SoftCredit__c>();
        for (npsp__SoftCredit__c sc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role__c, npsp__OpportunityContactRole__c 
            FROM npsp__SoftCredit__c 
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = (String)sc.npsp__Opportunity__c + '-' + (String)sc.npsp__Contact__c;
            scMap.put(key, sc);
        }

        // Prepare OCR Upsert and Deletion
        List<OpportunityContactRole> ocrUpsertList = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrDeleteList = new List<OpportunityContactRole>();
        // Track the specific OCR object to be used for each request
        Map<Integer, OpportunityContactRole> requestToOcrMap = new Map<Integer, OpportunityContactRole>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests.get(i);
            String key = (String)req.opportunityId + '-' + (String)req.contactId;
            List<OpportunityContactRole> existingOcrs = allOcrsByContactOpp.get(key);

            if (existingOcrs != null && !existingOcrs.isEmpty()) {
                // Requirement: Contact has exactly one OCR with the specified role.
                // We update the first existing OCR found and mark others for deletion.
                OpportunityContactRole ocrToUpdate = existingOcrs[0];
                ocrToUpdate.Role = req.role;
                ocrUpsertList.add(ocrToUpdate);
                requestToOcrMap.put(i, ocrToUpdate);

                if (existingOcrs.size() > 1) {
                    for (Integer j = 1; j < existingOcrs.size(); j++) {
                        ocrDeleteList.add(existingOcrs[j]);
                    }
                }
            } else {
                // No existing role found, create a new one.
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrUpsertList.add(newOcr);
                requestToOcrMap.put(i, newOcr);
            }
        }

        // Perform OCR DML
        if (!ocrUpsertList.isEmpty()) {
            upsert ocrUpsertList;
        }
        if (!ocrDeleteList.isEmpty()) {
