    /**
     * Reassigns ownership for a set of Accounts and all their associated Contacts.
     * 
     * This method bypasses Account trigger actions using the TAF framework to avoid 
     * expensive territory recalculations, while ensuring Contact trigger actions 
     * continue to run normally.
     *
     * @param accountIds Set of Account IDs to be reassigned.
     * @param newOwnerId The ID of the new owner for both Accounts and Contacts.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Use TAF's transaction bypass for the entire Account sObject.
        // This prevents TAF-registered actions from running on the Account trigger.
        TAF_Trigger_Framework.setBypass('Account', true);

        try {
            // 1. Retrieve existing Accounts to ensure we only update valid records.
            // This avoids System.TypeException if the input set contains non-Account IDs.
            List<Account> accountsToUpdate = [SELECT Id FROM Account WHERE Id IN :accountIds];
            for (Account acc : accountsToUpdate) {
                acc.OwnerId = newOwnerId;
            }

            // 2. Retrieve all Contacts associated with the provided Account IDs.
            // This is the second SOQL query.
            List<Contact> contactsToUpdate = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];
            for (Contact con : contactsToUpdate) {
                con.OwnerId = newOwnerId;
            }

            // 3. Consolidate records into a single list of SObjects to perform a single DML statement.
            // This ensures we stay well within the "at most two DML statements" constraint.
            List<SObject> allToUpdate = new List<SObject>();
            if (!accountsToUpdate.isEmpty()) {
                allToUpdate.addAll(accountsToUpdate);
            }
            if (!contactsToUpdate.isEmpty()) {
                allToUpdate.addAll(contactsToUpdate);
            }

            if (!allToUpdate.isEmpty()) {
                // All-or-none DML is the default behavior in Apex.
                // If this fails, the entire transaction (including Account updates) is rolled back.
                update allToUpdate;
            }
        } finally {
            // Ensure Account automation is restored for the rest of the transaction,
            // regardless of whether the DML succeeded or an exception was thrown.
            TAF_Trigger_Framework.setBypass('Account', false);
