```apex
public class TA_Opportunity_CollectForErpSync implements TA_Action {
    /**
     * Static set to persist IDs across multiple chunks of the same DML operation.
     * This allows us to aggregate all IDs before the finalizer runs.
     */
    public static final Set<Id> idsToSync = new Set<Id>();

    public void execute(TA_Context context) {
        if (context.getTriggerContext() == TriggerContext.AFTER_INSERT) {
            for (SObject so : context.getNewRecords()) {
                idsToSync.add(so.Id);
            }
        } else if (context.getTriggerContext() == TriggerContext.AFTER_UPDATE) {
            Map<Id, SObject> oldMap = (Map<Id, SObject>) context.getOldMap();
            for (SObject so : context.getNewRecords()) {
                Opportunity newOpp = (Opportunity) so;
                Opportunity oldOpp = (Opportunity) oldMap.get(so.Id);

                // Only collect IDs where the StageName has changed
                if (newOpp.StageName != oldOpp.StageName) {
                    idsToSync.add(so.Id);
                }
            }
        }
    }
}
