public class OpportunityErpSyncFinalizer implements TA_DML_Finalizer {
    /**
     * The DML finalizer runs at the end of the DML operation.
     * It enqueues the single job containing all collected IDs and clears the collection.
     */
    public void execute(TA_FinalizerContext context) {
