public class TA_Case_RollupOpenCount implements TriggerAction {
    public void execute(List<SObject> newList, Map<Id, SObject> oldMap, TriggerContext context) {
        Set<Id> accountIds = new Set<Id>();

        if (context == TriggerContext.AFTER_INSERT || context == TriggerContext.AFTER_UNDELETE) {
            if (newList != null) {
                for (SObject so : newList) {
                    Case c = (Case)so;
                    if (c.AccountId != null) {
                        accountIds.add(c.AccountId);
                    }
                }
            }
        } else if (context == TriggerContext.AFTER_UPDATE) {
            if (newList != null && oldMap != null) {
                for (SObject so : newList) {
                    Case cNew = (Case)so;
                    Case cOld = (Case)oldMap.get(so.Id);
                    if (cNew.AccountId != cOld.AccountId) {
                        if (cOld.AccountId != null) {
                            accountIds.add(cOld.AccountId);
                        }
                        if (cNew.AccountId != null) {
                            accountIds.add(cNew.AccountId);
                        }
                    } else if (cNew.IsClosed != cOld.IsClosed) {
                        if (cNew.AccountId != null) {
                            accountIds.add(cNew.AccountId);
                        }
                    }
                }
            }
        } else if (context == TriggerContext.AFTER_DELETE) {
            if (oldMap != null) {
                for (SObject so : oldMap.values()) {
                    Case cOld = (Case)so;
                    if (cOld.AccountId != null) {
                        accountIds.add(cOld.AccountId);
                    }
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Initialize map with 0 to ensure accounts with no open cases are reset to 0
        Map<Id, Integer> accountCounts = new Map<Id, Integer>();
        for (Id accId : accountIds) {
            accountCounts.put(accId, 0);
        }

        // Calculate current open case counts using one SOQL query
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt 
            FROM Case 
            WHERE IsClosed = false 
            AND AccountId IN :accountIds 
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Integer count = (Integer)ar.get('cnt');
            accountCounts.put(accId, count);
        }

        // Prepare the update list
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountCounts.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = accountCounts.get(accId)
            ));
        }

        // Perform one DML statement
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
